metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses and buys books online"

        bookshop = softwareSystem "Bookshop" "An online bookshop" {
            webStore = container "Web Store" "The web store where customers browse and purchase books" "Web"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Java"
        }

        customer -> webStore "Browses and purchases books" "HTTPS"
        webStore -> orderProcessor "Submits orders for processing" "REST/JSON"
    }

    views {
        systemContext bookshop "SystemContext" "The system context view of the Bookshop" {
            include *
            autoLayout
        }
    }
}
